import { Billboard, Text } from '@react-three/drei';
import { pixelToWorld } from './coordinateMapping';
import type { FloatingText } from '../types';

interface FloatingTextSpriteProps {
  text: FloatingText;
}

export default function FloatingTextSprite({ text }: FloatingTextSpriteProps) {
  const pos = pixelToWorld(text.x, text.y);
  const opacity = Math.max(0, text.opacity);
  const scale = text.scale ?? 1;

  if (opacity <= 0) return null;

  return (
    <Billboard position={[pos.x, 2.5 + (-text.offsetY * 0.02), pos.z]}>
      <Text
        fontSize={0.6 * scale}
        color={text.color}
        anchorX="center"
        anchorY="middle"
        font={undefined}
        fillOpacity={opacity}
        outlineWidth={0.05 * scale}
        outlineColor="#000000"
        outlineOpacity={opacity * 0.6}
        fontWeight={scale > 1.2 ? 'bold' : 'normal'}
      >
        {text.text}
      </Text>
    </Billboard>
  );
}
