import { useMemo } from 'react';
import * as THREE from 'three';
import { TILE_TYPES, GAME_CONFIG } from '../constants/config';
import { tileToWorld, TILE_WORLD } from './coordinateMapping';
import { getThemeMaterials, SHARED_MATERIALS } from './materialPalette';
import WaterTile from './WaterTile';
import PortalEffect from './PortalEffect';
import type { TileMap, RegionTheme } from '../types';

interface TileMapMeshProps {
  map: TileMap;
  theme: RegionTheme;
}

interface TileGroup {
  floor: THREE.Matrix4[];
  floorAlt: THREE.Matrix4[];
  wall: THREE.Matrix4[];
  shop: { pos: THREE.Vector3 }[];
  quest: { pos: THREE.Vector3 }[];
  crafting: { pos: THREE.Vector3 }[];
  water: { pos: THREE.Vector3; tileX: number }[];
  portal: { pos: THREE.Vector3 }[];
}

function classifyTiles(map: TileMap): TileGroup {
  const groups: TileGroup = {
    floor: [], floorAlt: [], wall: [],
    shop: [], quest: [], crafting: [],
    water: [], portal: [],
  };

  for (let y = 0; y < GAME_CONFIG.MAP_HEIGHT; y++) {
    for (let x = 0; x < GAME_CONFIG.MAP_WIDTH; x++) {
      const tile = map[y]?.[x] ?? 0;
      const center = tileToWorld(x, y);

      switch (tile) {
        case TILE_TYPES.WALL: {
          const m = new THREE.Matrix4().setPosition(center.x, 1.5, center.z);
          groups.wall.push(m);
          break;
        }
        case TILE_TYPES.PORTAL:
          groups.portal.push({ pos: new THREE.Vector3(center.x, 0, center.z) });
          // floor underneath
          addFloor(groups, x, y, center);
          break;
        case TILE_TYPES.SHOP:
          groups.shop.push({ pos: new THREE.Vector3(center.x, 0, center.z) });
          addFloor(groups, x, y, center);
          break;
        case TILE_TYPES.QUEST_BOARD:
          groups.quest.push({ pos: new THREE.Vector3(center.x, 0, center.z) });
          addFloor(groups, x, y, center);
          break;
        case TILE_TYPES.CRAFTING:
          groups.crafting.push({ pos: new THREE.Vector3(center.x, 0, center.z) });
          addFloor(groups, x, y, center);
          break;
        case TILE_TYPES.WATER:
          groups.water.push({ pos: new THREE.Vector3(center.x, 0.1, center.z), tileX: x });
          break;
        default: // FLOOR
          addFloor(groups, x, y, center);
          break;
      }
    }
  }
  return groups;
}

function addFloor(groups: TileGroup, x: number, y: number, center: THREE.Vector3) {
  const m = new THREE.Matrix4().setPosition(center.x, -0.1, center.z);
  if ((x + y) % 2 === 0) groups.floor.push(m);
  else groups.floorAlt.push(m);
}


// Better approach using direct ref
function InstancedGroup({ matrices, material }: {
  matrices: THREE.Matrix4[];
  material: THREE.Material;
  geoArgs: [number, number, number];
}) {
  const meshRef = useMemo(() => {
    if (matrices.length === 0) return null;
    const geo = new THREE.BoxGeometry(TILE_WORLD, 0.2, TILE_WORLD);
    const mesh = new THREE.InstancedMesh(geo, material, matrices.length);
    matrices.forEach((m, i) => mesh.setMatrixAt(i, m));
    mesh.instanceMatrix.needsUpdate = true;
    return mesh;
  }, [matrices, material]);

  if (!meshRef) return null;
  return <primitive object={meshRef} />;
}

function WallInstances({ matrices, material }: {
  matrices: THREE.Matrix4[];
  material: THREE.Material;
}) {
  const meshRef = useMemo(() => {
    if (matrices.length === 0) return null;
    const geo = new THREE.BoxGeometry(TILE_WORLD, 3, TILE_WORLD);
    const mesh = new THREE.InstancedMesh(geo, material, matrices.length);
    matrices.forEach((m, i) => mesh.setMatrixAt(i, m));
    mesh.instanceMatrix.needsUpdate = true;
    return mesh;
  }, [matrices, material]);

  if (!meshRef) return null;
  return <primitive object={meshRef} />;
}

export default function TileMapMesh({ map, theme }: TileMapMeshProps) {
  const materials = getThemeMaterials(theme);
  const groups = useMemo(() => classifyTiles(map), [map]);

  return (
    <group>
      {/* Floor tiles (instanced) */}
      <InstancedGroup matrices={groups.floor} material={materials.floor} geoArgs={[TILE_WORLD, 0.2, TILE_WORLD]} />
      <InstancedGroup matrices={groups.floorAlt} material={materials.floorAlt} geoArgs={[TILE_WORLD, 0.2, TILE_WORLD]} />

      {/* Wall tiles (instanced) */}
      <WallInstances matrices={groups.wall} material={materials.wall} />

      {/* Water tiles (individual for wave animation) */}
      {groups.water.map((w, i) => (
        <WaterTile key={`water-${i}`} position={[w.pos.x, w.pos.y, w.pos.z]} tileX={w.tileX} />
      ))}

      {/* Portal effects */}
      {groups.portal.map((p, i) => (
        <group key={`portal-${i}`}>
          {/* Floor under portal */}
          <mesh position={[p.pos.x, -0.1, p.pos.z]} material={materials.floor}>
            <boxGeometry args={[TILE_WORLD, 0.2, TILE_WORLD]} />
          </mesh>
          <PortalEffect position={[p.pos.x, 0, p.pos.z]} />
        </group>
      ))}

      {/* Shop stalls */}
      {groups.shop.map((s, i) => (
        <group key={`shop-${i}`} position={[s.pos.x, 0, s.pos.z]}>
          <mesh position={[0, 0.6, 0]} material={SHARED_MATERIALS.shop}>
            <boxGeometry args={[2, 1.2, 1.5]} />
          </mesh>
        </group>
      ))}

      {/* Quest boards */}
      {groups.quest.map((q, i) => (
        <group key={`quest-${i}`} position={[q.pos.x, 0, q.pos.z]}>
          <mesh position={[0, 1.0, 0]} material={SHARED_MATERIALS.questBoard}>
            <boxGeometry args={[1.5, 2.0, 0.2]} />
          </mesh>
        </group>
      ))}

      {/* Crafting anvils */}
      {groups.crafting.map((c, i) => (
        <group key={`craft-${i}`} position={[c.pos.x, 0, c.pos.z]}>
          <mesh position={[0, 0.4, 0]} material={SHARED_MATERIALS.crafting}>
            <cylinderGeometry args={[0.6, 0.8, 0.8, 6]} />
          </mesh>
        </group>
      ))}
    </group>
  );
}
