import { Canvas } from '@react-three/fiber';
import IsometricCamera from './IsometricCamera';
import GameScene from './GameScene';
import PostFX from './PostFX';
import { pixelToWorld } from './coordinateMapping';
import { GAME_STATES } from '../constants/config';
import { useGraphicsSettings } from '../hooks/useGraphicsSettings';
import { PerfOverlay, usePerfOverlayEnabled } from './PerfOverlay';
import type { GameState, Player, SpawnedMonster, Projectile, TileMap, DroppedItem, FloatingText } from '../types';

interface SceneRootProps {
  gameState: GameState;
  map: TileMap;
  player: Player;
  monsters: SpawnedMonster[];
  projectiles: Projectile[];
  droppedItems: DroppedItem[];
  floatingTexts: FloatingText[];
  currentRegion: string;
  lockedTargetUid?: string | null;
  skillRange?: number;
  onClickGround: (x: number, y: number) => void;
}

export default function SceneRoot(props: SceneRootProps) {
  const gfx = useGraphicsSettings();
  const perfEnabled = usePerfOverlayEnabled();
  const isDungeon = props.gameState === GAME_STATES.DUNGEON || props.gameState === GAME_STATES.BOSS;
  const isBoss = props.gameState === GAME_STATES.BOSS;
  const playerPos = pixelToWorld(props.player.x, props.player.y);

  // Dungeon: slightly muted ambient + warm torch-like point light following player.
  // Boss: cooler/dimmer with reddish tint to amp up tension (but still readable).
  const ambientIntensity = isBoss ? 0.45 : isDungeon ? 0.55 : 0.6;
  const ambientColor = isBoss ? '#5a3030' : isDungeon ? '#4a4258' : '#ffffff';
  const dirIntensity = isDungeon ? 0.6 : 0.8;
  const bgColor = isBoss ? '#1a0c10' : isDungeon ? '#1a1424' : '#1a1a2e';

  return (
    <Canvas
      orthographic
      gl={{ antialias: true, alpha: false, preserveDrawingBuffer: true }}
      style={{ width: '100%', height: '100%' }}
      camera={{ position: [0, 50, 0], zoom: 10, near: 0.1, far: 500 }}
    >
      <IsometricCamera />
      <ambientLight intensity={ambientIntensity} color={ambientColor} />
      <directionalLight position={[50, 80, 30]} intensity={dirIntensity} castShadow={false} />
      <directionalLight position={[-30, 40, -20]} intensity={isDungeon ? 0.3 : 0.3} />
      {isDungeon && gfx.dynamicLighting && (
        <pointLight
          position={[playerPos.x, 5, playerPos.z]}
          intensity={isBoss ? 1.8 : 1.5}
          distance={isBoss ? 22 : 28}
          decay={1.4}
          color={isBoss ? '#ffb04a' : '#ffd58a'}
        />
      )}
      <color attach="background" args={[bgColor]} />
      <GameScene {...props} />
      {gfx.postprocessing && (
        <PostFX
          hpRatio={props.player.maxHp > 0 ? props.player.hp / props.player.maxHp : 1}
          isDungeon={isDungeon}
          isBoss={isBoss}
        />
      )}
      {perfEnabled && <PerfOverlay />}
    </Canvas>
  );
}
