import { useEffect, useMemo, useRef } from 'react';
import { useThree, useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { sampleShake } from './cameraShake';
import { useGameState } from '../stores/useWorldStore';
import { GAME_STATES } from '../constants/config';

/** 보스 인트로 줌 효과 (ms). 진입 직후 카메라가 잠깐 클로즈업되었다가 원래대로. */
const BOSS_INTRO_DURATION_MS = 1200;
/** 인트로 피크에서의 줌 배율 (1.0 = 변화 없음, 1.4 = 40% 확대) */
const BOSS_INTRO_ZOOM_PEAK = 1.4;

export default function IsometricCamera() {
  const { camera, size } = useThree();
  const wasShakingRef = useRef(false);
  const baseZoomRef = useRef(1);
  const bossIntroStartRef = useRef(0);
  const gameState = useGameState();

  const basePos = useMemo(() => {
    const azimuth = Math.PI / 4;
    const elevation = Math.PI / 6;
    const distance = 80;
    const cx = distance * Math.cos(elevation) * Math.sin(azimuth);
    const cy = distance * Math.sin(elevation);
    const cz = distance * Math.cos(elevation) * Math.cos(azimuth);
    const centerX = 50;
    const centerZ = 30;
    return new THREE.Vector3(centerX + cx, cy, centerZ + cz);
  }, []);

  const lookAt = useMemo(() => new THREE.Vector3(50, 0, 30), []);

  useEffect(() => {
    if (!(camera instanceof THREE.OrthographicCamera)) return;
    camera.position.copy(basePos);
    camera.lookAt(lookAt);
    const zoom = Math.min(size.width / 120, size.height / 80);
    baseZoomRef.current = zoom;
    camera.zoom = zoom;
    camera.updateProjectionMatrix();
  }, [camera, size, basePos, lookAt]);

  // Boss intro: 매번 BOSS 화면에 진입할 때 줌 펄스 시작
  useEffect(() => {
    if (gameState === GAME_STATES.BOSS) {
      bossIntroStartRef.current = Date.now();
    } else {
      bossIntroStartRef.current = 0;
      if (camera instanceof THREE.OrthographicCamera && camera.zoom !== baseZoomRef.current) {
        camera.zoom = baseZoomRef.current;
        camera.updateProjectionMatrix();
      }
    }
  }, [gameState, camera]);

  useFrame(() => {
    if (!(camera instanceof THREE.OrthographicCamera)) return;

    // Boss intro zoom pulse: half-sine envelope, peaks mid-duration, returns to baseline.
    const introStart = bossIntroStartRef.current;
    if (introStart > 0) {
      const elapsed = Date.now() - introStart;
      if (elapsed < BOSS_INTRO_DURATION_MS) {
        const t = elapsed / BOSS_INTRO_DURATION_MS;
        const envelope = Math.sin(t * Math.PI); // 0 → 1 → 0
        const zoomMult = 1 + (BOSS_INTRO_ZOOM_PEAK - 1) * envelope;
        camera.zoom = baseZoomRef.current * zoomMult;
        camera.updateProjectionMatrix();
      } else if (elapsed >= BOSS_INTRO_DURATION_MS) {
        camera.zoom = baseZoomRef.current;
        camera.updateProjectionMatrix();
        bossIntroStartRef.current = 0;
      }
    }

    const s = sampleShake();
    const shaking = s.x !== 0 || s.y !== 0;
    if (shaking) {
      camera.position.set(basePos.x + s.x, basePos.y + s.y, basePos.z + s.x);
      camera.lookAt(lookAt);
      wasShakingRef.current = true;
    } else if (wasShakingRef.current) {
      camera.position.copy(basePos);
      camera.lookAt(lookAt);
      wasShakingRef.current = false;
    }
  });

  return null;
}
