import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import type * as THREE from 'three';
import { SHARED_MATERIALS } from './materialPalette';

interface PortalEffectProps {
  position: [number, number, number];
}

export default function PortalEffect({ position }: PortalEffectProps) {
  const ringRef = useRef<THREE.Mesh>(null);
  const discRef = useRef<THREE.Mesh>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime;
    if (ringRef.current) {
      ringRef.current.rotation.y = t * 1.5;
      (ringRef.current.material as THREE.MeshStandardMaterial).emissiveIntensity = 0.4 + Math.sin(t * 3) * 0.3;
    }
    if (discRef.current) {
      (discRef.current.material as THREE.MeshStandardMaterial).opacity = 0.3 + Math.sin(t * 2) * 0.15;
    }
  });

  return (
    <group position={position}>
      {/* Rotating torus ring */}
      <mesh ref={ringRef} position={[0, 1.5, 0]} material={SHARED_MATERIALS.portal}>
        <torusGeometry args={[1.2, 0.2, 8, 24]} />
      </mesh>
      {/* Inner translucent disc */}
      <mesh ref={discRef} position={[0, 1.5, 0]} material={SHARED_MATERIALS.portalDisc}>
        <circleGeometry args={[1.0, 16]} />
      </mesh>
      {/* Point light glow */}
      <pointLight position={[0, 1.5, 0]} color="#9333ea" intensity={2} distance={6} />
    </group>
  );
}
