import * as THREE from 'three';
import { TILE_WORLD } from './coordinateMapping';

const cache: Record<string, THREE.BufferGeometry> = {};

function getOrCreate(key: string, factory: () => THREE.BufferGeometry): THREE.BufferGeometry {
  if (!cache[key]) cache[key] = factory();
  return cache[key];
}

// Tile geometries
export const floorGeo = () => getOrCreate('floor', () => new THREE.BoxGeometry(TILE_WORLD, 0.2, TILE_WORLD));
export const wallGeo = () => getOrCreate('wall', () => new THREE.BoxGeometry(TILE_WORLD, 3, TILE_WORLD));
export const portalRingGeo = () => getOrCreate('portalRing', () => new THREE.TorusGeometry(1.2, 0.2, 8, 24));
export const portalDiscGeo = () => getOrCreate('portalDisc', () => new THREE.CircleGeometry(1.0, 16));
