import { memo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import type * as THREE from 'three';
import { pixelToWorld } from './coordinateMapping';
import { SHARED_MATERIALS } from './materialPalette';
import {
  bodyGeo,
  headGeo,
  hatGeo,
  eyeGeo,
  shadowGeo,
  armGeo,
  handGeo,
  bootGeo,
  capeGeo,
  beltGeo,
  buckleGeo,
  swordBladeGeo,
  swordHiltGeo,
  swordGuardGeo,
} from './geometryFactory';

interface PlayerMeshProps {
  x: number;
  y: number;
}

function PlayerMeshImpl({ x, y }: PlayerMeshProps) {
  const groupRef = useRef<THREE.Group>(null);
  const leftArmRef = useRef<THREE.Group>(null);
  const rightArmRef = useRef<THREE.Group>(null);
  const capeRef = useRef<THREE.Mesh>(null);

  const pos = pixelToWorld(x, y);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime;
    if (groupRef.current) {
      groupRef.current.position.y = Math.sin(t * 2) * 0.05;
    }
    const swing = Math.sin(t * 2) * 0.1;
    if (leftArmRef.current) leftArmRef.current.rotation.x = swing;
    if (rightArmRef.current) rightArmRef.current.rotation.x = -swing;
    if (capeRef.current) capeRef.current.rotation.x = -0.25 + Math.sin(t * 1.4) * 0.04;
  });

  return (
    <group position={[pos.x, 0, pos.z]}>
      <group ref={groupRef}>
        <mesh position={[0, 0.02, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={shadowGeo()} material={SHARED_MATERIALS.shadow} />

        {/* Boots at floor level */}
        <mesh position={[-0.22, 0.1, 0.06]} geometry={bootGeo()} material={SHARED_MATERIALS.boots} />
        <mesh position={[0.22, 0.1, 0.06]} geometry={bootGeo()} material={SHARED_MATERIALS.boots} />

        {/* Body (torso) */}
        <mesh position={[0, 1.1, 0]} geometry={bodyGeo()} material={SHARED_MATERIALS.playerBody} />

        {/* Belt around waist + buckle */}
        <mesh position={[0, 0.55, 0]} rotation={[Math.PI / 2, 0, 0]} geometry={beltGeo()} material={SHARED_MATERIALS.belt} />
        <mesh position={[0, 0.55, 0.54]} geometry={buckleGeo()} material={SHARED_MATERIALS.buckle} />

        {/* Cape on back */}
        <mesh
          ref={capeRef}
          position={[0, 1.35, -0.5]}
          rotation={[-0.25, 0, 0]}
          geometry={capeGeo()}
          material={SHARED_MATERIALS.cape}
        />

        {/* Arms (shoulders at y ~ 1.85) */}
        <group ref={leftArmRef} position={[-0.7, 1.85, 0]}>
          <mesh position={[0, -0.48, 0]} geometry={armGeo()} material={SHARED_MATERIALS.playerBody} />
          <mesh position={[0, -0.98, 0]} geometry={handGeo()} material={SHARED_MATERIALS.playerHead} />
        </group>
        <group ref={rightArmRef} position={[0.7, 1.85, 0]}>
          <mesh position={[0, -0.48, 0]} geometry={armGeo()} material={SHARED_MATERIALS.playerBody} />
          <mesh position={[0, -0.98, 0]} geometry={handGeo()} material={SHARED_MATERIALS.playerHead} />
        </group>

        {/* Sword on right hip */}
        <group position={[0.55, 0.55, 0.1]} rotation={[0, -0.3, -Math.PI / 7]}>
          <mesh position={[0, -0.4, 0]} geometry={swordBladeGeo()} material={SHARED_MATERIALS.steel} />
          <mesh position={[0, 0.05, 0]} geometry={swordGuardGeo()} material={SHARED_MATERIALS.steel} />
          <mesh position={[0, 0.18, 0]} geometry={swordHiltGeo()} material={SHARED_MATERIALS.woodHilt} />
        </group>

        {/* Head */}
        <mesh position={[0, 2.3, 0]} geometry={headGeo()} material={SHARED_MATERIALS.playerHead} />

        {/* Hat */}
        <mesh position={[0, 2.7, 0]} geometry={hatGeo()} material={SHARED_MATERIALS.playerHat} />

        {/* Eyes */}
        <mesh position={[-0.18, 2.35, 0.4]} geometry={eyeGeo()} material={SHARED_MATERIALS.playerEye} />
        <mesh position={[0.18, 2.35, 0.4]} geometry={eyeGeo()} material={SHARED_MATERIALS.playerEye} />
      </group>
    </group>
  );
}

export default memo(PlayerMeshImpl);
