import { useEffect, useState } from 'react';
import { getGraphicsSettings, subscribeGraphics, type GraphicsSettings } from '../utils/graphicsSettings';

/** 그래픽 설정 구독 - 변경 시 컴포넌트 리렌더 */
export function useGraphicsSettings(): Readonly<GraphicsSettings> {
  const [s, setS] = useState(getGraphicsSettings());
  useEffect(() => subscribeGraphics(() => setS({ ...getGraphicsSettings() })), []);
  return s;
}
