import { useCallback, useEffect, useMemo } from 'react';
import type { ThreeEvent } from '@react-three/fiber';
import { GAME_CONFIG, GAME_STATES, TILE_TYPES } from '../constants/config';
import { getNPCsForRegion, REGIONS } from '../constants/regions';
import { pixelToWorld, tileToWorld, worldToPixel, SCALE, TILE_WORLD } from './coordinateMapping';
import TileMapMesh from './TileMapMesh';
import PlayerMesh from './PlayerMesh';
import MonsterMesh from './MonsterMesh';
import NPCMesh from './NPCMesh';
import ProjectileMesh from './ProjectileMesh';
import DroppedItemMesh from './DroppedItemMesh';
import FloatingTextSprite from './FloatingTextSprite';
import ParticleField from './ParticleField';
import { useGraphicsSettings } from '../hooks/useGraphicsSettings';
import { onHoverEnter, onHoverLeave, resetHoverCursor } from './hoverCursor';
import type { GameState, Player, SpawnedMonster, Projectile, TileMap, DroppedItem, FloatingText } from '../types';

interface GameSceneProps {
  gameState: GameState;
  map: TileMap;
  player: Player;
  monsters: SpawnedMonster[];
  projectiles: Projectile[];
  droppedItems: DroppedItem[];
  floatingTexts: FloatingText[];
  currentRegion: string;
  lockedTargetUid?: string | null;
  /** 현재 선택 스킬의 사거리(픽셀). 0이면 표시 안 함. */
  skillRange?: number;
  onClickGround: (x: number, y: number) => void;
}

export default function GameScene({
  gameState,
  map,
  player,
  monsters,
  projectiles,
  droppedItems,
  floatingTexts,
  currentRegion,
  lockedTargetUid,
  skillRange = 0,
  onClickGround,
}: GameSceneProps) {
  const gfx = useGraphicsSettings();
  const region = REGIONS[currentRegion];
  const theme = region?.theme || 'port';
  const npcs = gameState === GAME_STATES.TOWN ? getNPCsForRegion(currentRegion) : [];

  const handleGroundClick = useCallback((e: ThreeEvent<MouseEvent>) => {
    const point = e.point;
    if (point) {
      const { x, y } = worldToPixel(point.x, point.z);
      onClickGround(x, y);
    }
  }, [onClickGround]);

  const handleEntityClick = useCallback((entityX: number, entityY: number) => {
    onClickGround(entityX, entityY);
  }, [onClickGround]);

  // 포탈 타일 위치를 모아 호버 센서 평면으로 덮어 커서 변경 + 클릭 위임.
  const portalTiles = useMemo(() => {
    const tiles: Array<{ tileX: number; tileY: number }> = [];
    for (let y = 0; y < GAME_CONFIG.MAP_HEIGHT; y++) {
      for (let x = 0; x < GAME_CONFIG.MAP_WIDTH; x++) {
        if (map[y]?.[x] === TILE_TYPES.PORTAL) tiles.push({ tileX: x, tileY: y });
      }
    }
    return tiles;
  }, [map]);

  // Scene unmount / 게임 상태 전환 시 커서 원복
  useEffect(() => resetHoverCursor, []);

  return (
    <group>
      {/* Ground click plane (invisible) */}
      <mesh
        position={[50, -0.05, 30]}
        rotation={[-Math.PI / 2, 0, 0]}
        onClick={handleGroundClick}
      >
        <planeGeometry args={[120, 80]} />
        <meshBasicMaterial visible={false} />
      </mesh>

      {/* Portal hover sensors — invisible tile-sized planes for cursor + click forwarding */}
      {portalTiles.map(({ tileX, tileY }) => {
        const c = tileToWorld(tileX, tileY);
        const px = (tileX + 0.5) * GAME_CONFIG.TILE_SIZE;
        const py = (tileY + 0.5) * GAME_CONFIG.TILE_SIZE;
        return (
          <mesh
            key={`portal-hover-${tileX}-${tileY}`}
            position={[c.x, 0.05, c.z]}
            rotation={[-Math.PI / 2, 0, 0]}
            onClick={(e) => { e.stopPropagation(); onClickGround(px, py); }}
            onPointerOver={(e) => { e.stopPropagation(); onHoverEnter(); }}
            onPointerOut={() => onHoverLeave()}
          >
            <planeGeometry args={[TILE_WORLD, TILE_WORLD]} />
            <meshBasicMaterial visible={false} />
          </mesh>
        );
      })}

      {/* Tile map */}
      <TileMapMesh map={map} theme={theme} />

      {/* NPCs (town only) */}
      {npcs.map(npc => (
        <NPCMesh
          key={npc.id}
          npc={npc}
          onClick={() => handleEntityClick(npc.x, npc.y)}
        />
      ))}

      {/* Dropped items */}
      {droppedItems.map(item => (
        <DroppedItemMesh
          key={item.uid}
          item={item}
          onClick={() => handleEntityClick(item.x, item.y)}
        />
      ))}

      {/* Monsters */}
      {monsters.map(monster => (
        <MonsterMesh
          key={monster.uid}
          monster={monster}
          isLocked={lockedTargetUid === monster.uid}
          onClick={() => handleEntityClick(monster.x, monster.y)}
        />
      ))}

      {/* Projectiles */}
      {projectiles.map(proj => (
        <ProjectileMesh key={proj.id} projectile={proj} />
      ))}

      {/* Skill range telegraph (DUNGEON/BOSS only) — outer ring + faint fill */}
      {skillRange > 0 && (gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && (() => {
        const c = pixelToWorld(player.x, player.y);
        const rWorld = skillRange * SCALE;
        const ringWidth = Math.max(0.18, rWorld * 0.06);
        return (
          <group position={[c.x, 0.04, c.z]}>
            {/* Faint disc fill */}
            <mesh rotation={[-Math.PI / 2, 0, 0]} renderOrder={1}>
              <circleGeometry args={[rWorld, 64]} />
              <meshBasicMaterial color="#ffd700" transparent opacity={0.07} depthWrite={false} />
            </mesh>
            {/* Bright outer ring */}
            <mesh position={[0, 0.01, 0]} rotation={[-Math.PI / 2, 0, 0]} renderOrder={2}>
              <ringGeometry args={[Math.max(0, rWorld - ringWidth), rWorld, 64]} />
              <meshBasicMaterial color="#ffd700" transparent opacity={0.75} depthWrite={false} />
            </mesh>
          </group>
        );
      })()}

      {/* Player */}
      <PlayerMesh x={player.x} y={player.y} />

      {/* Death particles (gated by graphics settings) */}
      {gfx.particles && <ParticleField />}

      {/* Floating texts (gated by graphics settings) */}
      {gfx.floatingText && floatingTexts.map(ft => (
        <FloatingTextSprite key={ft.id} text={ft} />
      ))}
    </group>
  );
}
