import { memo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Trail } from '@react-three/drei';
import type * as THREE from 'three';
import { pixelToWorld } from './coordinateMapping';
import { bulletGeo, cannonGeo, lightningGeo, waveGeo, rockGeo } from './geometryFactory';
import { getGlowMaterial } from './materialPalette';
import { useGraphicsSettings } from '../hooks/useGraphicsSettings';
import type { Projectile } from '../types';

interface ProjectileMeshProps {
  projectile: Projectile;
}

type GeoKey = 'bullet' | 'cannon' | 'lightning' | 'wave' | 'rock';

const PROJECTILE_CONFIG: Record<string, { color: string; emissive: string; intensity: number; geoKey: GeoKey }> = {
  cutlass:      { color: '#ffffff', emissive: '#ffffff', intensity: 0.8, geoKey: 'bullet' },
  cannonball:   { color: '#333333', emissive: '#000000', intensity: 0.3, geoKey: 'cannon' },
  thunderstorm: { color: '#6A5ACD', emissive: '#FFD700', intensity: 0.9, geoKey: 'lightning' },
  tidal_wave:   { color: '#1E90FF', emissive: '#1E90FF', intensity: 0.7, geoKey: 'wave' },
  earthquake:   { color: '#8B4513', emissive: '#8B4513', intensity: 0.4, geoKey: 'rock' },
};

function getGeo(key: GeoKey): THREE.BufferGeometry {
  switch (key) {
    case 'bullet':    return bulletGeo();
    case 'cannon':    return cannonGeo();
    case 'lightning': return lightningGeo();
    case 'wave':      return waveGeo();
    case 'rock':      return rockGeo();
  }
}

function ProjectileMeshImpl({ projectile }: ProjectileMeshProps) {
  const groupRef = useRef<THREE.Group>(null);
  const meshRef = useRef<THREE.Mesh>(null);
  const pos = pixelToWorld(projectile.x, projectile.y);
  const config = PROJECTILE_CONFIG[projectile.type] || PROJECTILE_CONFIG.cutlass;
  const material = getGlowMaterial(config.color, config.emissive, config.intensity);
  const geometry = getGeo(config.geoKey);
  const gfx = useGraphicsSettings();

  useFrame(({ clock }) => {
    if (!groupRef.current) return;
    groupRef.current.rotation.y = clock.elapsedTime * 8;
    groupRef.current.rotation.x = clock.elapsedTime * 4;
  });

  return (
    <group position={[pos.x, 1.2, pos.z]}>
      {gfx.particles ? (
        <Trail width={1.2} color={config.emissive} length={4} decay={1.5} attenuation={(w) => w}>
          <group ref={groupRef}>
            <mesh ref={meshRef} geometry={geometry} material={material} />
          </group>
        </Trail>
      ) : (
        <group ref={groupRef}>
          <mesh ref={meshRef} geometry={geometry} material={material} />
        </group>
      )}
      <pointLight color={config.emissive} intensity={1} distance={3} />
    </group>
  );
}

export default memo(ProjectileMeshImpl, (prev, next) => (
  prev.projectile.id === next.projectile.id &&
  prev.projectile.x === next.projectile.x &&
  prev.projectile.y === next.projectile.y
));
