import { memo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Billboard, Text } from '@react-three/drei';
import type * as THREE from 'three';
import { pixelToWorld } from './coordinateMapping';
import { SHARED_MATERIALS, getNpcBodyMaterial } from './materialPalette';
import { onHoverEnter, onHoverLeave } from './hoverCursor';
import {
  bodyGeo,
  headGeo,
  eyeGeo,
  shadowGeo,
  barrelGeo,
  crateGeo,
  anvilGeo,
  hammerHeadGeo,
  hammerHandleGeo,
  scrollGeo,
  swordBladeGeo,
  swordGuardGeo,
  swordHiltGeo,
} from './geometryFactory';
import type { NPC } from '../types';

interface NPCMeshProps {
  npc: NPC;
  onClick: () => void;
}

const NPC_ACCENT: Record<string, string> = {
  shop: '#e67e22',
  crafting: '#95a5a6',
  quest: '#9b59b6',
  mercenary: '#e74c3c',
};

function NPCMeshImpl({ npc, onClick }: NPCMeshProps) {
  const groupRef = useRef<THREE.Group>(null);
  const scrollRef = useRef<THREE.Mesh>(null);
  const pos = pixelToWorld(npc.x, npc.y);
  const accent = NPC_ACCENT[npc.type] || '#ffffff';
  const bodyMaterial = getNpcBodyMaterial(accent);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime + npc.x;
    if (groupRef.current) groupRef.current.position.y = Math.sin(t * 1.5) * 0.03;
    if (scrollRef.current) scrollRef.current.rotation.z = 0.4 + Math.sin(t * 2) * 0.08;
  });

  return (
    <group
      position={[pos.x, 0, pos.z]}
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      onPointerOver={(e) => { e.stopPropagation(); onHoverEnter(); }}
      onPointerOut={() => onHoverLeave()}
    >
      <group ref={groupRef}>
        <mesh position={[0, 0.02, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={shadowGeo()} material={SHARED_MATERIALS.shadow} />

        <mesh position={[0, 1.1, 0]} geometry={bodyGeo()} material={bodyMaterial} />

        <mesh position={[0, 2.3, 0]} geometry={headGeo()} material={SHARED_MATERIALS.playerHead} />

        <mesh position={[-0.18, 2.35, 0.4]} geometry={eyeGeo()} material={SHARED_MATERIALS.playerEye} />
        <mesh position={[0.18, 2.35, 0.4]} geometry={eyeGeo()} material={SHARED_MATERIALS.playerEye} />

        {npc.type === 'shop' && (
          <>
            <mesh position={[0.95, 0.35, 0.1]} geometry={barrelGeo()} material={SHARED_MATERIALS.barrel} />
            <mesh position={[0.95, 0.98, 0.1]} rotation={[0, 0.3, 0]} geometry={crateGeo()} material={SHARED_MATERIALS.crate} />
          </>
        )}

        {npc.type === 'crafting' && (
          <>
            <mesh position={[0.95, 0.4, 0.1]} geometry={anvilGeo()} material={SHARED_MATERIALS.steelDark} />
            <group position={[0.55, 1.35, 0.05]} rotation={[0, 0, -0.6]}>
              <mesh position={[0, 0.28, 0]} geometry={hammerHeadGeo()} material={SHARED_MATERIALS.hammerHead} />
              <mesh position={[0, 0, 0]} geometry={hammerHandleGeo()} material={SHARED_MATERIALS.woodHilt} />
            </group>
          </>
        )}

        {npc.type === 'quest' && (
          <mesh
            ref={scrollRef}
            position={[0.55, 1.4, 0.15]}
            rotation={[0, 0, 0.4]}
            geometry={scrollGeo()}
            material={SHARED_MATERIALS.scrollGlow}
          />
        )}

        {npc.type === 'mercenary' && (
          <>
            <group position={[0.6, 1.2, 0]} rotation={[0, 0, 0.35]}>
              <mesh position={[0, 0.42, 0]} geometry={swordBladeGeo()} material={SHARED_MATERIALS.steel} />
              <mesh position={[0, 0, 0]} geometry={swordGuardGeo()} material={SHARED_MATERIALS.steel} />
              <mesh position={[0, -0.12, 0]} geometry={swordHiltGeo()} material={SHARED_MATERIALS.woodHilt} />
            </group>
            <group position={[-0.6, 1.2, 0]} rotation={[0, 0, -0.35]}>
              <mesh position={[0, 0.42, 0]} geometry={swordBladeGeo()} material={SHARED_MATERIALS.steel} />
              <mesh position={[0, 0, 0]} geometry={swordGuardGeo()} material={SHARED_MATERIALS.steel} />
              <mesh position={[0, -0.12, 0]} geometry={swordHiltGeo()} material={SHARED_MATERIALS.woodHilt} />
            </group>
          </>
        )}
      </group>

      <Billboard position={[0, 3.2, 0]}>
        <Text fontSize={0.4} color="#ffffff" anchorX="center" anchorY="middle" font={undefined}>
          {npc.name}
        </Text>
      </Billboard>
    </group>
  );
}

export default memo(NPCMeshImpl, (prev, next) => (
  prev.npc.id === next.npc.id &&
  prev.npc.x === next.npc.x &&
  prev.npc.y === next.npc.y &&
  prev.onClick === next.onClick
));
