import { memo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Billboard, Text } from '@react-three/drei';
import type * as THREE from 'three';
import { pixelToWorld } from './coordinateMapping';
import {
  monsterBodyGeo,
  monsterBodyRoundGeo,
  monsterHeadGeo,
  monsterEyeGeo,
  monsterShadowGeo,
  wingGeo,
  crownGeo,
  hpBarBgGeo,
  tailSegGeo,
  clawGeo,
  antennaGeo,
  orbGeo,
} from './geometryFactory';
import {
  SHARED_MATERIALS,
  getMonsterBodyMaterial,
  getMonsterWingMaterial,
  getHpFillMaterial,
} from './materialPalette';
import { onHoverEnter, onHoverLeave } from './hoverCursor';
import type { SpawnedMonster, StatusEffectType } from '../types';

/** 상태이상 종류별 작은 아이콘 (몬스터 머리 위 오버레이용) */
const STATUS_ICONS: Record<StatusEffectType, string> = {
  burn: '🔥',
  bleed: '🩸',
  slow: '❄️',
  stun: '⚡',
};

type MonsterShape = 'humanoid' | 'beast' | 'serpent' | 'bird' | 'elemental' | 'undead' | 'aquatic';

const SHAPES: Record<string, MonsterShape> = {
  bandit: 'humanoid', pirate: 'humanoid', minotaur: 'humanoid', temple_guardian: 'humanoid',
  wild_boar: 'beast', golem: 'beast', giant_crab: 'aquatic',
  sea_serpent: 'serpent', shark: 'serpent', kraken: 'serpent',
  seagull: 'bird', harpy: 'bird', griffin: 'bird', ice_wyvern: 'bird', phoenix: 'bird', dragon: 'bird',
  storm_elemental: 'elemental',
  mermaid: 'aquatic', ghost_ship: 'aquatic',
  mummy: 'undead',
  desert_scorpion: 'beast',
};

function getShape(id: string): MonsterShape {
  return SHAPES[id] ?? 'beast';
}

function hpColor(pct: number): string {
  return pct > 0.5 ? '#2ecc71' : pct > 0.25 ? '#f39c12' : '#e74c3c';
}

interface MonsterMeshProps {
  monster: SpawnedMonster;
  isLocked?: boolean;
  onClick: () => void;
}

function MonsterMeshImpl({ monster, isLocked, onClick }: MonsterMeshProps) {
  const groupRef = useRef<THREE.Group>(null);
  const tailRef = useRef<THREE.Group>(null);
  const orbRef = useRef<THREE.Group>(null);
  const pos = pixelToWorld(monster.x, monster.y);
  const scale = (monster.size / 30) * 0.8;
  const shape = getShape(monster.id);

  const bodyMaterial = getMonsterBodyMaterial(monster.color);
  const eyeMaterial = monster.isBoss ? SHARED_MATERIALS.monsterEyeBoss : SHARED_MATERIALS.monsterEye;
  const isRoundBody = shape === 'serpent' || shape === 'aquatic';
  const isBird = shape === 'bird';
  const baseY = isBird ? 0.5 : 0;

  useFrame(({ clock }) => {
    const t = clock.elapsedTime + monster.uid.charCodeAt(0);
    if (groupRef.current) {
      groupRef.current.position.y = baseY + Math.sin(t * 2) * 0.08;
    }
    if (tailRef.current) {
      tailRef.current.rotation.y = Math.sin(t * 3) * 0.4;
    }
    if (orbRef.current) {
      orbRef.current.rotation.y = t * 1.5;
    }
  });

  const hpPercent = monster.currentHp / monster.maxHp;

  return (
    <group
      position={[pos.x, 0, pos.z]}
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      onPointerOver={(e) => { e.stopPropagation(); onHoverEnter(); }}
      onPointerOut={() => onHoverLeave()}
    >
      <group ref={groupRef} scale={[scale, scale, scale]}>
        <mesh position={[0, 0.02, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={monsterShadowGeo()} material={SHARED_MATERIALS.shadow} />

        <mesh
          position={[0, 1.0, 0]}
          geometry={isRoundBody ? monsterBodyRoundGeo() : monsterBodyGeo()}
          material={bodyMaterial}
        />

        <mesh position={[0, 2.0, 0]} geometry={monsterHeadGeo()} material={bodyMaterial} />

        <mesh position={[-0.15, 2.05, 0.35]} geometry={monsterEyeGeo()} material={eyeMaterial} />
        <mesh position={[0.15, 2.05, 0.35]} geometry={monsterEyeGeo()} material={eyeMaterial} />

        {isBird && (
          <>
            <mesh position={[-1.0, 1.4, 0]} rotation={[0, 0, 0.3]} geometry={wingGeo()} material={getMonsterWingMaterial(monster.color)} />
            <mesh position={[1.0, 1.4, 0]} rotation={[0, 0, -0.3]} geometry={wingGeo()} material={getMonsterWingMaterial(monster.color)} />
          </>
        )}

        {shape === 'serpent' && (
          <group ref={tailRef} position={[0, 0.8, -0.7]}>
            <mesh position={[0, 0, 0]} geometry={tailSegGeo()} material={bodyMaterial} scale={[0.9, 0.9, 0.9]} />
            <mesh position={[0, -0.2, -0.5]} geometry={tailSegGeo()} material={bodyMaterial} scale={[0.7, 0.7, 0.7]} />
            <mesh position={[0, -0.35, -0.9]} geometry={tailSegGeo()} material={bodyMaterial} scale={[0.5, 0.5, 0.5]} />
          </group>
        )}

        {shape === 'beast' && (
          <>
            <mesh position={[-0.55, 0.6, 0.55]} rotation={[Math.PI / 2, 0, 0.3]} geometry={clawGeo()} material={SHARED_MATERIALS.claw} />
            <mesh position={[-0.25, 0.6, 0.65]} rotation={[Math.PI / 2, 0, 0.1]} geometry={clawGeo()} material={SHARED_MATERIALS.claw} />
            <mesh position={[0.25, 0.6, 0.65]} rotation={[Math.PI / 2, 0, -0.1]} geometry={clawGeo()} material={SHARED_MATERIALS.claw} />
            <mesh position={[0.55, 0.6, 0.55]} rotation={[Math.PI / 2, 0, -0.3]} geometry={clawGeo()} material={SHARED_MATERIALS.claw} />
          </>
        )}

        {shape === 'elemental' && (
          <>
            <mesh position={[-0.2, 2.55, 0]} rotation={[0, 0, 0.2]} geometry={antennaGeo()} material={SHARED_MATERIALS.claw} />
            <mesh position={[0.2, 2.55, 0]} rotation={[0, 0, -0.2]} geometry={antennaGeo()} material={SHARED_MATERIALS.claw} />
            <group ref={orbRef} position={[0, 1.2, 0]}>
              <mesh position={[1.0, 0, 0]} geometry={orbGeo()} material={getMonsterWingMaterial(monster.color)} />
              <mesh position={[-1.0, 0, 0]} geometry={orbGeo()} material={getMonsterWingMaterial(monster.color)} />
            </group>
          </>
        )}

        {shape === 'undead' && (
          <>
            <mesh position={[-0.12, 1.92, 0.4]} rotation={[Math.PI, 0, 0]} geometry={clawGeo()} material={SHARED_MATERIALS.fang} scale={[0.6, 0.6, 0.6]} />
            <mesh position={[0.12, 1.92, 0.4]} rotation={[Math.PI, 0, 0]} geometry={clawGeo()} material={SHARED_MATERIALS.fang} scale={[0.6, 0.6, 0.6]} />
          </>
        )}

        {shape === 'aquatic' && (
          <>
            <mesh position={[-0.55, 1.1, -0.2]} rotation={[0, 0, -Math.PI / 3]} geometry={wingGeo()} material={getMonsterWingMaterial(monster.color)} scale={[0.6, 0.6, 0.6]} />
            <mesh position={[0.55, 1.1, -0.2]} rotation={[0, 0, Math.PI / 3]} geometry={wingGeo()} material={getMonsterWingMaterial(monster.color)} scale={[0.6, 0.6, 0.6]} />
          </>
        )}

        {monster.isBoss && (
          <mesh position={[0, 2.6, 0]} geometry={crownGeo()} material={SHARED_MATERIALS.bossCrown} />
        )}

        {monster.isElite && !monster.isBoss && (
          <mesh position={[0, 0.06, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.95, 1.15, 32]} />
            <meshBasicMaterial color="#ffd700" transparent opacity={0.7} depthWrite={false} />
          </mesh>
        )}

        {isLocked && (
          <group position={[0, 3.2, 0]}>
            <mesh rotation={[Math.PI, 0, 0]}>
              <coneGeometry args={[0.35, 0.7, 4]} />
              <meshBasicMaterial color="#ffd700" />
            </mesh>
          </group>
        )}
      </group>

      {!monster.isBoss && (
        <Billboard position={[0, scale * 3 + 0.5, 0]}>
          <mesh position={[0, 0, 0]} geometry={hpBarBgGeo()} material={SHARED_MATERIALS.hpBarBg} />
          <mesh position={[(hpPercent - 1) * 0.95, 0, 0.01]} material={getHpFillMaterial(hpColor(hpPercent))}>
            <planeGeometry args={[1.9 * hpPercent, 0.2]} />
          </mesh>
          {monster.isElite && (
            <Text position={[0, 0.5, 0]} fontSize={0.4} color="#ffd700" anchorX="center" anchorY="middle" font={undefined}>
              {'★ ELITE'}
            </Text>
          )}
        </Billboard>
      )}

      {monster.isBoss && (
        <Billboard position={[0, scale * 3.5 + 0.5, 0]}>
          <Text fontSize={0.5} color="#ff4444" anchorX="center" anchorY="middle" font={undefined}>
            {'👑'} {monster.name}
          </Text>
        </Billboard>
      )}

      {/* 상태이상 오버레이: HP바 위에 작은 아이콘들 가로 나열 */}
      {monster.statusEffects && monster.statusEffects.length > 0 && (
        <Billboard position={[0, scale * 3 + 1.2, 0]}>
          {monster.statusEffects.map((eff, i) => {
            const offset = (i - (monster.statusEffects!.length - 1) / 2) * 0.55;
            return (
              <Text
                key={eff.type}
                position={[offset, 0, 0]}
                fontSize={0.4}
                anchorX="center"
                anchorY="middle"
                font={undefined}
              >
                {STATUS_ICONS[eff.type]}
              </Text>
            );
          })}
        </Billboard>
      )}
    </group>
  );
}

export default memo(MonsterMeshImpl, (prev, next) => {
  const a = prev.monster;
  const b = next.monster;
  return (
    a.uid === b.uid &&
    a.x === b.x &&
    a.y === b.y &&
    a.currentHp === b.currentHp &&
    a.isBoss === b.isBoss &&
    a.isElite === b.isElite &&
    a.statusEffects === b.statusEffects &&
    prev.isLocked === next.isLocked &&
    prev.onClick === next.onClick
  );
});
