import { memo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import type * as THREE from 'three';
import { pixelToWorld } from './coordinateMapping';
import { getRarityColor } from '../utils/combat';
import { itemGeo } from './geometryFactory';
import { getGlowMaterial } from './materialPalette';
import { onHoverEnter, onHoverLeave } from './hoverCursor';
import type { DroppedItem } from '../types';

interface DroppedItemMeshProps {
  item: DroppedItem;
  onClick: () => void;
}

function DroppedItemMeshImpl({ item, onClick }: DroppedItemMeshProps) {
  const groupRef = useRef<THREE.Group>(null);
  const pos = pixelToWorld(item.x, item.y);
  const isChest = item.type === 'chest';
  const color = isChest ? '#ff9800' : getRarityColor(item.rarity);
  const material = getGlowMaterial(color, color, isChest ? 0.55 : 0.3);
  const scale = isChest ? 2.2 : 1;

  useFrame(({ clock }) => {
    if (!groupRef.current) return;
    const t = clock.elapsedTime + item.x * 0.01;
    groupRef.current.rotation.y = isChest ? Math.sin(t * 1.6) * 0.3 : t * 2;
    groupRef.current.position.y = (isChest ? 0.4 : 0.6) + Math.sin(t * (isChest ? 1.8 : 3)) * (isChest ? 0.08 : 0.15);
  });

  return (
    <group
      position={[pos.x, 0, pos.z]}
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      onPointerOver={(e) => { e.stopPropagation(); onHoverEnter(); }}
      onPointerOut={() => onHoverLeave()}
    >
      <group ref={groupRef} scale={scale}>
        <mesh geometry={itemGeo()} material={material} />
      </group>
      <pointLight color={color} intensity={isChest ? 1.6 : 0.8} distance={isChest ? 5 : 3} position={[0, 0.8, 0]} />
    </group>
  );
}

export default memo(DroppedItemMeshImpl, (prev, next) => (
  prev.item.uid === next.item.uid &&
  prev.item.x === next.item.x &&
  prev.item.y === next.item.y &&
  prev.onClick === next.onClick
));
