import * as THREE from 'three';
import type { RegionTheme } from '../types';

interface ThemeMaterials {
  floor: THREE.MeshStandardMaterial;
  floorAlt: THREE.MeshStandardMaterial;
  wall: THREE.MeshStandardMaterial;
  bg: THREE.Color;
}

const cache = new Map<string, ThemeMaterials>();

function hex(color: string): THREE.Color {
  return new THREE.Color(color);
}

function darken(color: string, amount: number): string {
  const c = new THREE.Color(color);
  c.multiplyScalar(1 - amount);
  return '#' + c.getHexString();
}

const THEME_COLORS: Record<RegionTheme, { bg: string; floor: string; wall: string }> = {
  port:    { bg: '#1a2634', floor: '#2a3a4a', wall: '#4a5568' },
  desert:  { bg: '#2d2418', floor: '#3d3020', wall: '#8B7355' },
  forest:  { bg: '#1a2d1a', floor: '#2a3d2a', wall: '#4a5568' },
  castle:  { bg: '#1f1f2e', floor: '#2a2a3d', wall: '#4a5568' },
  marble:  { bg: '#2a2a3a', floor: '#3a3a4a', wall: '#4a4a5a' },
  exotic:  { bg: '#2d1a1a', floor: '#3d2a2a', wall: '#4a5568' },
};

export function getThemeMaterials(theme: RegionTheme): ThemeMaterials {
  if (cache.has(theme)) return cache.get(theme)!;

  const colors = THEME_COLORS[theme] || THEME_COLORS.port;

  const materials: ThemeMaterials = {
    floor: new THREE.MeshStandardMaterial({ color: colors.floor, roughness: 0.8, metalness: 0.1 }),
    floorAlt: new THREE.MeshStandardMaterial({ color: darken(colors.floor, 0.12), roughness: 0.8, metalness: 0.1 }),
    wall: new THREE.MeshStandardMaterial({ color: colors.wall, roughness: 0.6, metalness: 0.2 }),
    bg: hex(colors.bg),
  };

  cache.set(theme, materials);
  return materials;
}

// Per-color monster body material cache (one MeshStandardMaterial per unique color)
const monsterBodyCache = new Map<string, THREE.MeshStandardMaterial>();
export function getMonsterBodyMaterial(color: string): THREE.MeshStandardMaterial {
  let m = monsterBodyCache.get(color);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.1 });
    monsterBodyCache.set(color, m);
  }
  return m;
}

// Translucent wing material per color (used for SKY-type monsters)
const monsterWingCache = new Map<string, THREE.MeshStandardMaterial>();
export function getMonsterWingMaterial(color: string): THREE.MeshStandardMaterial {
  let m = monsterWingCache.get(color);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color, side: THREE.DoubleSide, transparent: true, opacity: 0.8 });
    monsterWingCache.set(color, m);
  }
  return m;
}

// HP bar fill material per HP-bracket color
const hpFillCache = new Map<string, THREE.MeshBasicMaterial>();
export function getHpFillMaterial(color: string): THREE.MeshBasicMaterial {
  let m = hpFillCache.get(color);
  if (!m) {
    m = new THREE.MeshBasicMaterial({ color });
    hpFillCache.set(color, m);
  }
  return m;
}

// NPC body material (one per accent color)
const npcBodyCache = new Map<string, THREE.MeshStandardMaterial>();
export function getNpcBodyMaterial(color: string): THREE.MeshStandardMaterial {
  let m = npcBodyCache.get(color);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color, roughness: 0.55, metalness: 0.05 });
    npcBodyCache.set(color, m);
  }
  return m;
}

// Glowy emissive material per color (used for projectiles & dropped items)
const glowCache = new Map<string, THREE.MeshStandardMaterial>();
export function getGlowMaterial(color: string, emissive = color, intensity = 0.5): THREE.MeshStandardMaterial {
  const key = `${color}|${emissive}|${intensity}`;
  let m = glowCache.get(key);
  if (!m) {
    m = new THREE.MeshStandardMaterial({
      color,
      emissive,
      emissiveIntensity: intensity,
      roughness: 0.3,
      metalness: 0.2,
    });
    glowCache.set(key, m);
  }
  return m;
}

