import { useEffect, useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { pixelToWorld, SCALE } from './coordinateMapping';
import { getParticles, tickParticles } from './particles';

const MAX = 200;
const dummy = new THREE.Object3D();
const tmpColor = new THREE.Color();

/**
 * InstancedMesh 기반 파티클 필드. 매 프레임 particles 모듈을 tick 후
 * 살아있는 입자만큼 인스턴스를 갱신. 보이지 않는 인스턴스는 scale=0 으로 가림.
 */
export default function ParticleField() {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const lastTimeRef = useRef(performance.now());
  const initialColors = useMemo(() => new Float32Array(MAX * 3), []);

  useEffect(() => {
    const mesh = meshRef.current;
    if (!mesh) return;
    mesh.instanceColor = new THREE.InstancedBufferAttribute(initialColors, 3);
    mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
  }, [initialColors]);

  useFrame(() => {
    const mesh = meshRef.current;
    if (!mesh) return;

    const now = performance.now();
    const dt = now - lastTimeRef.current;
    lastTimeRef.current = now;

    tickParticles(dt);
    const particles = getParticles();

    for (let i = 0; i < MAX; i++) {
      const p = particles[i];
      if (!p) {
        dummy.scale.set(0, 0, 0);
        dummy.position.set(0, -100, 0);
      } else {
        const pos = pixelToWorld(p.x, p.y);
        const heightOffset = (p.maxLife - p.life) / 1000 * p.vz * SCALE * -0.001 + 0.5;
        dummy.position.set(pos.x, Math.max(0.05, heightOffset), pos.z);
        const lifeRatio = p.life / p.maxLife;
        const s = p.scale * lifeRatio;
        dummy.scale.set(s, s, s);
        mesh.setColorAt(i, tmpColor.set(p.color));
      }
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  });

  return (
    <instancedMesh ref={meshRef} args={[undefined, undefined, MAX]} frustumCulled={false}>
      <sphereGeometry args={[0.15, 6, 6]} />
      <meshBasicMaterial transparent opacity={0.9} depthWrite={false} />
    </instancedMesh>
  );
}
