/**
 * 개발용 r3f 성능 오버레이.
 *
 * 활성화 방법 (둘 중 하나):
 *   1) URL에 `?perf` 또는 `?perf=1` 추가하면 자동 활성화 (영구 활성화는 localStorage 저장)
 *   2) 게임 중 backtick(`) 키로 토글
 *
 * 토글 상태는 localStorage('bc_perf_overlay')에 저장되어 새로고침 시 유지.
 * 프로덕션 빌드에서도 동작하지만 일반 사용자가 우연히 켤 일은 거의 없음 — 키 단축키 기준.
 */
import { useEffect, useState } from 'react';
import { Perf } from 'r3f-perf';

const STORAGE_KEY = 'bc_perf_overlay';
const listeners = new Set<() => void>();
let cached: boolean | null = null;

function readInitial(): boolean {
  // URL param wins (always sets/clears localStorage so it survives reloads)
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.has('perf')) {
      const v = params.get('perf');
      const enabled = v === null || v === '' || v === '1' || v === 'true';
      localStorage.setItem(STORAGE_KEY, enabled ? '1' : '0');
      return enabled;
    }
    return localStorage.getItem(STORAGE_KEY) === '1';
  } catch {
    return false;
  }
}

export function isPerfOverlayEnabled(): boolean {
  if (cached === null) cached = readInitial();
  return cached;
}

export function setPerfOverlayEnabled(enabled: boolean): void {
  cached = enabled;
  try { localStorage.setItem(STORAGE_KEY, enabled ? '1' : '0'); } catch { /* noop */ }
  for (const l of listeners) l();
}

export function subscribePerfOverlay(fn: () => void): () => void {
  listeners.add(fn);
  return () => { listeners.delete(fn); };
}

// Global hotkey: backtick toggles overlay. Registered once at module load.
if (typeof window !== 'undefined') {
  window.addEventListener('keydown', (e) => {
    if (e.key === '`' && !e.repeat && !(e.target instanceof HTMLInputElement) && !(e.target instanceof HTMLTextAreaElement)) {
      setPerfOverlayEnabled(!isPerfOverlayEnabled());
    }
  });
}

/**
 * Canvas 안에 마운트하여 FPS / draw calls / triangles 등을 표시.
 * SceneRoot에서 isPerfOverlayEnabled() 구독해 토글.
 */
export function PerfOverlay() {
  return <Perf position="top-right" matrixUpdate />;
}

/** React hook — overlay 토글 상태에 따라 컴포넌트 리렌더 */
export function usePerfOverlayEnabled(): boolean {
  const [enabled, setEnabled] = useState(() => isPerfOverlayEnabled());
  useEffect(() => subscribePerfOverlay(() => setEnabled(isPerfOverlayEnabled())), []);
  return enabled;
}
