import { EffectComposer, Bloom, Vignette, ChromaticAberration } from '@react-three/postprocessing';
import { BlendFunction, KernelSize } from 'postprocessing';
import { Vector2 } from 'three';
import { useMemo } from 'react';

/**
 * 포스트프로세싱 효과 체인.
 *
 * - Bloom: 발광 픽셀(스킬/포탈/엘리트 등 emissive 머티리얼)을 부드럽게 확산
 * - Vignette: 던전/보스에서 화면 가장자리 어둡게 (몰입감)
 * - ChromaticAberration: 저체력일 때 가장자리 색번짐 (긴장감) — hpRatio < 0.3에서 발동
 *
 * 토글: useGraphicsSettings().postprocessing (low quality에서는 off)
 */
interface PostFXProps {
  /** 현재 HP 비율 (0..1). 0.3 미만일 때 색수차 강화 */
  hpRatio: number;
  /** 던전/보스 화면 (vignette 강도 조절) */
  isDungeon: boolean;
  isBoss: boolean;
}

export default function PostFX({ hpRatio, isDungeon, isBoss }: PostFXProps) {
  // ChromaticAberration offset은 Vector2 인스턴스 필요. low-hp 강도 매핑.
  // hpRatio 0.3 ~ 0.0 → offset 0.0005 ~ 0.004 (선형)
  const lowHpFactor = hpRatio < 0.3 ? Math.max(0, 1 - hpRatio / 0.3) : 0;
  const caOffset = useMemo(() => new Vector2(0.0005 + lowHpFactor * 0.0035, 0.0005 + lowHpFactor * 0.0035), [lowHpFactor]);

  // Vignette darkness: 일반은 약하게, 보스에서 강하게
  const vignetteDarkness = isBoss ? 0.65 : isDungeon ? 0.5 : 0.3;
  const vignetteOffset = isBoss ? 0.25 : 0.4;

  return (
    <EffectComposer multisampling={0}>
      <Bloom
        intensity={0.7}
        kernelSize={KernelSize.LARGE}
        luminanceThreshold={0.55}
        luminanceSmoothing={0.2}
        mipmapBlur
      />
      <Vignette
        offset={vignetteOffset}
        darkness={vignetteDarkness}
        blendFunction={BlendFunction.NORMAL}
      />
      <ChromaticAberration
        offset={caOffset}
        radialModulation
        modulationOffset={0.15}
        blendFunction={BlendFunction.NORMAL}
      />
    </EffectComposer>
  );
}
