import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import type * as THREE from 'three';
import { TILE_WORLD } from './coordinateMapping';
import { SHARED_MATERIALS } from './materialPalette';
import { useGraphicsSettings } from '../hooks/useGraphicsSettings';

interface WaterTileProps {
  position: [number, number, number];
  tileX: number;
}

export default function WaterTile({ position, tileX }: WaterTileProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const gfx = useGraphicsSettings();

  useFrame(({ clock }) => {
    if (!gfx.waterShader) return;
    const mesh = meshRef.current;
    if (!mesh) return;
    const geo = mesh.geometry;
    const pos = geo.attributes.position;
    const time = clock.elapsedTime;

    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const z = pos.getY(i); // PlaneGeometry: x,y → world x,z
      pos.setZ(i, Math.sin(time * 2 + x * 1.5 + tileX) * 0.15 + Math.cos(time * 1.5 + z * 2) * 0.1);
    }
    pos.needsUpdate = true;
    geo.computeVertexNormals();
  });

  return (
    <mesh ref={meshRef} position={position} rotation={[-Math.PI / 2, 0, 0]} material={SHARED_MATERIALS.water}>
      <planeGeometry args={[TILE_WORLD, TILE_WORLD, 8, 8]} />
    </mesh>
  );
}
