/**
 * 2D↔3D 좌표 변환 유틸 - SCALE=0.1 (1px = 0.1 world unit)
 * 게임 로직(2D 픽셀) → Three.js 3D 씬 좌표 매핑
 */
import * as THREE from 'three';
import { GAME_CONFIG } from '../constants/config';

/** 스케일 팩터: 1픽셀 = 0.1 Three.js 월드 단위 */
const SCALE = 0.1;
/** 타일 하나의 3D 월드 크기 (40px × 0.1 = 4 단위) */
const TILE_WORLD = GAME_CONFIG.TILE_SIZE * SCALE;

/** 2D 픽셀 좌표를 3D 월드 좌표로 변환 (Y축은 높이) */
export function pixelToWorld(px: number, py: number, elevation = 0): THREE.Vector3 {
  return new THREE.Vector3(
    px * SCALE,
    elevation,
    py * SCALE
  );
}

/** 타일 그리드 좌표를 3D 월드 좌표로 변환 (타일 중심점) */
export function tileToWorld(tileX: number, tileY: number): THREE.Vector3 {
  return new THREE.Vector3(
    (tileX + 0.5) * TILE_WORLD,
    0,
    (tileY + 0.5) * TILE_WORLD
  );
}

export function worldToPixel(worldX: number, worldZ: number): { x: number; y: number } {
  return {
    x: worldX / SCALE,
    y: worldZ / SCALE,
  };
}

export { SCALE, TILE_WORLD };
