/**
 * R3F 상호작용 오브젝트 호버 시 브라우저 커서를 pointer 로 전환.
 * onPointerOver / onPointerOut 핸들러에 그대로 바인딩해서 사용.
 */

let hoverCount = 0;

function setCursor(value: string) {
  if (typeof document === 'undefined') return;
  document.body.style.cursor = value;
}

export function onHoverEnter() {
  hoverCount++;
  setCursor('pointer');
}

export function onHoverLeave() {
  hoverCount = Math.max(0, hoverCount - 1);
  if (hoverCount === 0) setCursor('');
}

/** Scene unmount 시 잔여 포인터 커서 상태를 초기화. */
export function resetHoverCursor() {
  hoverCount = 0;
  setCursor('');
}
